<script setup lang="ts">
import AppLayout from "@/layouts/AppLayout.vue";
import { router, useForm } from "@inertiajs/vue3";

defineOptions({ layout: AppLayout });
defineProps<{ categories: any[]; levels: any[]; degrees: any[] }>();
const categoryForm = useForm({ key: "", name: "", description: "", masonic_degree_id: "" });
const partForm = useForm({ key: "", ritual_category_id: "", name: "", description: "", counts_toward_program: false, point_value: "" });
const levelForm = useForm({ key: "", name: "", point_threshold: "" });
const createCategory = () => categoryForm.post("/platform/ritual-categories", { onSuccess: () => categoryForm.reset() });
const createPart = () => partForm.post("/platform/ritual-parts", { onSuccess: () => partForm.reset() });
const createLevel = () => levelForm.post("/platform/ritual-levels", { onSuccess: () => levelForm.reset() });
const saveCategory = (category: any) => router.put(`/platform/ritual-categories/${category.id}`, category);
const savePart = (part: any) => router.put(`/platform/ritual-parts/${part.id}`, part);
const saveLevel = (level: any) => router.put(`/platform/ritual-levels/${level.id}`, level);
const warning = (item: any) => `Changes that affect points, thresholds, or active state can affect ${item.affected_person_count} credited member record${item.affected_person_count === 1 ? "" : "s"}.`;
</script>

