    <main class="mx-auto w-full max-w-6xl space-y-8 p-4 sm:p-6 lg:p-8"><header><h1 class="text-2xl font-bold">Ritual Reference</h1><p class="mt-1 text-sm text-muted-foreground">Platform-wide catalog. Stable keys cannot change. Deactivate records instead of deleting them.</p></header>
        <section class="space-y-3 rounded-lg border p-4"><h2 class="font-semibold">Categories</h2><form class="grid gap-2 md:grid-cols-4" @submit.prevent="createCategory"><input v-model="categoryForm.name" required placeholder="Category name" class="rounded border bg-background p-2" /><input v-model="categoryForm.key" placeholder="Stable key (optional)" class="rounded border bg-background p-2" /><select v-model="categoryForm.masonic_degree_id" class="rounded border bg-background p-2"><option value="">No degree</option><option v-for="degree in degrees" :key="degree.id" :value="degree.id">{{ degree.name }}</option></select><button class="rounded bg-primary px-3 py-2 text-primary-foreground">Add category</button></form><form v-for="category in categories" :key="category.id" class="rounded border p-3" @submit.prevent="saveCategory(category)"><div class="grid gap-2 md:grid-cols-5"><input v-model="category.name" required class="rounded border bg-background p-2" /><input :value="category.key" disabled aria-label="Stable category key" class="rounded border bg-muted p-2" /><select v-model="category.masonic_degree_id" class="rounded border bg-background p-2"><option :value="null">No degree</option><option v-for="degree in degrees" :key="degree.id" :value="degree.id">{{ degree.name }}</option></select><input v-model.number="category.sort_order" type="number" min="0" class="rounded border bg-background p-2" /><label class="flex items-center gap-2"><input v-model="category.is_active" type="checkbox" /> Active</label></div><textarea v-model="category.description" class="mt-2 w-full rounded border bg-background p-2" placeholder="Description" /><p class="mt-2 text-xs text-muted-foreground">{{ warning(category) }}</p><label class="mt-2 flex items-center gap-2 text-sm"><input v-model="category.confirm_impact" type="checkbox" /> Confirm any impact change</label><button class="mt-2 rounded border px-3 py-2">Save category</button></form></section>
