rt.description" class="mt-2 w-full rounded border bg-background p-2" placeholder="Description" /><p class="mt-2 text-xs text-muted-foreground">{{ warning(part) }}</p><label class="mt-2 flex items-center gap-2 text-sm"><input v-model="part.confirm_impact" type="checkbox" /> Confirm any impact change</label><button class="mt-2 rounded border px-3 py-2">Save part</button></form></div></section>
